C = "anabolic-steroids"

AAS_INTL = [("United Kingdom", "Class C; possession for personal use is not an offence, but supply is"), ("Canada", "Schedule IV of the Controlled Drugs and Substances Act"), ("Australia", "Schedule 4 prescription medicine; import controls apply"), ("International", "Not under UN control; banned in sport by WADA")]

AAS_LEGAL = ["{name} is a Schedule III controlled substance under the Anabolic Steroid Control Acts of 1990 and 2004. {extra}[^dea]",
             "<b>Possession:</b>|under federal law, possessing anabolic steroids without a valid prescription can bring up to one year in prison and a minimum fine of $1,000 for a first offense.[^possession]",
             "<b>Selling or importing:</b>|distributing Schedule III substances can bring up to 10 years in prison for a first offense. Products bought online are often seized at the border.[^trafficking]",
             "<b>Sport:</b>|all anabolic steroids are banned by the World Anti-Doping Agency and US sports organizations."]

def aas_legal(name, extra=""):
    return [s.format(name=name, extra=extra) for s in AAS_LEGAL]

