AAS_FAKES = "<strong>Fake and contaminated products:</strong> most steroids are bought from underground labs or online. Tests often find wrong ingredients or doses, and injectable products can be non-sterile."

def aas_overdose(name):
    return f"{name} does not usually cause acute overdose. Harms build over time: seek emergency care for chest pain, signs of stroke, yellowing skin or eyes, severe abdominal pain, or thoughts of self-harm.[^steroids]"

